#!/usr/bin/env python3
"""Underline every headline in the unpacked quarterly_report.docx.

Headlines in this report are the ALL-CAPS section title lines (no heading
styles exist in the document). Each headline paragraph's non-empty text is
entirely uppercase, so we target those paragraphs and add <w:u w:val="single"/>
to every text-bearing run while leaving all other content untouched.
"""
import os
from defusedxml import minidom

XML = os.path.join("quarterly_report_unpacked", "word", "document.xml")
dom = minidom.parse(XML)


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        parts.append(t.firstChild.nodeValue if t.firstChild else "")
    return "".join(parts)


headlines = []
for p in dom.getElementsByTagName("w:p"):
    text = para_text(p).strip()
    if not text or not text.isupper():
        continue  # empty lines, body prose, bullets, table rows, dividers
    underlined_runs = 0
    for r in p.getElementsByTagName("w:r"):
        has_text = any(
            t.firstChild and t.firstChild.nodeValue.strip()
            for t in r.getElementsByTagName("w:t")
        )
        if not has_text:
            continue
        rpr = None
        for child in r.childNodes:
            if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
                rpr = child
                break
        if rpr is None:
            rpr = dom.createElement("w:rPr")
            r.insertBefore(rpr, r.firstChild)
        for existing in rpr.getElementsByTagName("w:u"):
            rpr.removeChild(existing)
        u = dom.createElement("w:u")
        u.setAttribute("w:val", "single")
        rpr.appendChild(u)
        underlined_runs += 1
    if underlined_runs:
        headlines.append((text, underlined_runs))

with open(XML, "wb") as f:
    f.write(dom.toxml(encoding="UTF-8"))

print(f"Underlined {len(headlines)} headline paragraph(s):")
for text, n in headlines:
    print(f"- {text} ({n} run(s))")

"""Underline all headline paragraphs in the unpacked quarterly_report.docx.

Headlines are the report's section titles: paragraphs whose text contains at
least one letter and where every letter is uppercase (body text, bullet
lines, table rows, and the dash separator do not match this pattern).
Formatting change only - no tracked changes.
"""
import io
from xml.dom import minidom

XML_PATH = 'unpacked/word/document.xml'
W_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'


def is_el(node, name):
    return (node.nodeType == node.ELEMENT_NODE and node.namespaceURI == W_NS
            and node.localName == name)


def children(parent, name):
    return [c for c in parent.childNodes if is_el(c, name)]


def text_of(node, tag):
    parts = []
    for t in node.getElementsByTagNameNS(W_NS, tag):
        for tn in t.childNodes:
            if tn.nodeType == tn.TEXT_NODE:
                parts.append(tn.data)
    return ''.join(parts)


def is_headline(text):
    letters = [c for c in text if c.isalpha()]
    return bool(letters) and all(c.isupper() for c in letters)


doc = minidom.parse(XML_PATH)
body = next(c for c in doc.documentElement.childNodes if is_el(c, 'body'))

headlines_underlined = []
for p in children(body, 'p'):
    if not is_headline(text_of(p, 't')):
        continue
    for r in children(p, 'r'):
        run_text = text_of(r, 't')
        if not run_text.strip():
            continue
        rprs = children(r, 'rPr')
        rpr = rprs[0] if rprs else None
        if rpr is None:
            rpr = doc.createElementNS(W_NS, 'w:rPr')
            r.insertBefore(rpr, r.firstChild)
        if not children(rpr, 'u'):
            u = doc.createElementNS(W_NS, 'w:u')
            u.setAttributeNS(W_NS, 'w:val', 'single')
            rpr.appendChild(u)
        headlines_underlined.append(run_text.strip())

buf = io.StringIO()
doc.writexml(buf, indent='  ', addindent='  ', newl='\n', encoding='utf-8')
with open(XML_PATH, 'w', encoding='utf-8') as f:
    f.write(buf.getvalue())

print('Underlined %d headline paragraphs:' % len(set(headlines_underlined)))
for h in sorted(set(headlines_underlined)):
    print(' - %s' % h)

